<% content_for(:title, "Quizzy · #{@quiz.title} · Game #{@game.code}") %>
<section class="cover cover--blue cover--calm">
<div class="screen" id="screen-root" data-state-url="<%= state_moderate_quiz_game_path(@quiz, @game) %>">
  <div class="screen__top">
    <span class="logo screen__logo"><span class="logo__mark">?</span>Quizzy</span>
    <span id="top-quiz-title"><%= @quiz.title %></span>
  </div>

  <div class="screen__body">
    <!-- Lobby: before start -->
    <div id="view-lobby" <%= 'hidden' unless @game.waiting? %>>
      <div class="lobby">
        <div>
          <h1 class="lobby__title" id="quiz-title"><%= @quiz.title %></h1>
          <div class="lobby__join">Join at</div>
          <div class="lobby__url" id="join-url"><%= @join_url_display %></div>
          <div class="counter-pill" id="players-counter">Players: <%= @players_count %></div>
        </div>
        <div class="qr" id="qr-code" role="img" aria-label="QR code for <%= @join_url_display %>" data-join-url="<%= @join_url_display %>"><%== @qr_svg %></div>
      </div>
    </div>

    <!-- Question: open or closed -->
    <div id="view-question" <%= 'hidden' unless @game.playing? %>>
      <div class="stage-question__num" id="question-progress"><% if @current_question %>Question <%= (@game.current_index || 0) + 1 %> of <%= @total %><% end %></div>
      <div class="stage-question__body" id="question-body"><%= @current_question&.body %></div>
      <ul class="stage-options <%= 'stage-options--results' if @game.closed? %>" id="options-list">
        <% if @current_question %>
          <% max_count = @current_question.options.map { |o| @counts[o.id] || 0 }.max || 0 %>
          <% total_answers = @answers_count > 0 ? @answers_count : 1 %>
          <% @current_question.options.order(:position, :id).each_with_index do |opt, i| %>
            <% letter = ("A".ord + i).chr %>
            <% count = @counts[opt.id] || 0 %>
            <% share = @game.closed? ? (count.to_f * 100.0 / total_answers) : 0 %>
            <li class="stage-option <%= 'is-correct' if @game.closed? && opt.correct? %>" data-option-id="<%= opt.id %>">
              <span class="stage-option__bar" style="--share: <%= share.round(1) %>%"></span>
              <span class="stage-option__letter"><%= letter %></span>
              <span class="stage-option__title"><%= opt.text %></span>
              <% if @game.closed? %>
                <span class="stage-option__count"><%= count %></span>
                <% if opt.correct? %>
                  <span class="stage-option__mark">Correct</span>
                <% end %>
              <% end %>
            </li>
          <% end %>
        <% end %>
      </ul>
      <div style="margin-top: 24px">
        <span class="answers-counter" id="answers-counter">Answers: <%= @answers_count %> / <%= @players_count %></span>
      </div>
    </div>

    <!-- Over: after end -->
    <div id="view-over" <%= 'hidden' unless @game.finished? %>>
      <div class="screen__kicker"><%= @quiz.title %></div>
      <div class="stage-question__body" id="over-message">The quiz is over</div>
    </div>
  </div>

  <div class="screen-controls">
    <div class="screen-controls__info">
      <%= link_to "Back to quiz", moderate_quiz_path(@quiz) %>
      <span id="game-code">Game <%= @game.code %></span>
    </div>
    <div class="buttons">
      <span id="btn-start" <%= 'hidden' unless @game.waiting? %>>
        <%= form_with url: start_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false } do %>
          <button type="submit" class="btn btn--pink btn--lg">Start</button>
        <% end %>
      </span>
      <span id="btn-finish" <%= 'hidden' unless @game.open? %>>
        <%= form_with url: finish_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false } do %>
          <button type="submit" class="btn btn--pink btn--lg">Finish</button>
        <% end %>
      </span>
      <span id="btn-next" <%= 'hidden' unless @game.closed? && !@game.last_question? %>>
        <%= form_with url: next_question_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false } do %>
          <button type="submit" class="btn btn--pink btn--lg">Next</button>
        <% end %>
      </span>
      <span id="btn-end" <%= 'hidden' unless @game.closed? && @game.last_question? %>>
        <%= form_with url: end_quiz_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false } do %>
          <button type="submit" class="btn btn--pink btn--lg">End quiz</button>
        <% end %>
      </span>
    </div>
  </div>
</div>
</section>

<script>
(function() {
  var root = document.getElementById('screen-root');
  if (!root) return;
  var stateUrl = root.getAttribute('data-state-url');
  var viewLobby = document.getElementById('view-lobby');
  var viewQuestion = document.getElementById('view-question');
  var viewOver = document.getElementById('view-over');
  var playersCounter = document.getElementById('players-counter');
  var answersCounter = document.getElementById('answers-counter');
  var progressEl = document.getElementById('question-progress');
  var bodyEl = document.getElementById('question-body');
  var optionsList = document.getElementById('options-list');
  var btnStart = document.getElementById('btn-start');
  var btnFinish = document.getElementById('btn-finish');
  var btnNext = document.getElementById('btn-next');
  var btnEnd = document.getElementById('btn-end');

  function setHidden(el, hidden) {
    if (!el) return;
    if (hidden) el.setAttribute('hidden', '');
    else el.removeAttribute('hidden');
  }

  function letterFor(i) {
    return String.fromCharCode(65 + i);
  }

  function renderOptions(options, status, answersCount) {
    if (!optionsList) return;
    // Clear and rebuild (small lists, crowded Wi-Fi friendly: tiny DOM)
    while (optionsList.firstChild) optionsList.removeChild(optionsList.firstChild);
    var isClosed = (status === 'closed');
    if (isClosed) optionsList.classList.add('stage-options--results');
    else optionsList.classList.remove('stage-options--results');
    var total = answersCount > 0 ? answersCount : 1;
    options.forEach(function(opt, idx) {
      var li = document.createElement('li');
      li.className = 'stage-option' + ((isClosed && opt.correct) ? ' is-correct' : '');
      li.setAttribute('data-option-id', opt.id);

      var bar = document.createElement('span');
      bar.className = 'stage-option__bar';
      var share = 0;
      if (isClosed) {
        var c = opt.count || 0;
        share = (c * 100.0 / total);
      }
      bar.setAttribute('style', '--share: ' + share.toFixed(1) + '%');
      li.appendChild(bar);

      var letter = document.createElement('span');
      letter.className = 'stage-option__letter';
      letter.textContent = letterFor(idx);
      li.appendChild(letter);

      var title = document.createElement('span');
      title.className = 'stage-option__title';
      title.textContent = opt.text;
      li.appendChild(title);

      if (isClosed) {
        var count = document.createElement('span');
        count.className = 'stage-option__count';
        count.textContent = String(opt.count || 0);
        li.appendChild(count);

        if (opt.correct) {
          var mark = document.createElement('span');
          mark.className = 'stage-option__mark';
          mark.textContent = 'Correct';
          li.appendChild(mark);
        }
      }

      optionsList.appendChild(li);
    });
  }

  function render(state) {
    var status = state.status;
    var total = state.total || 0;
    var idx = (state.current_index === null || state.current_index === undefined) ? 0 : state.current_index;
    var players = state.players_count || 0;
    var answers = state.answers_count || 0;

    if (status === 'waiting') {
      setHidden(viewLobby, false);
      setHidden(viewQuestion, true);
      setHidden(viewOver, true);
      if (playersCounter) playersCounter.textContent = 'Players: ' + players;
      setHidden(btnStart, false);
      setHidden(btnFinish, true);
      setHidden(btnNext, true);
      setHidden(btnEnd, true);
    } else if (status === 'open' || status === 'closed') {
      setHidden(viewLobby, true);
      setHidden(viewQuestion, false);
      setHidden(viewOver, true);
      if (progressEl) progressEl.textContent = 'Question ' + (idx + 1) + ' of ' + total;
      if (bodyEl) bodyEl.textContent = state.question ? state.question.body : '';
      if (state.question && state.question.options) {
        renderOptions(state.question.options, status, answers);
      }
      if (answersCounter) answersCounter.textContent = 'Answers: ' + answers + ' / ' + players;
      var isLast = !!state.is_last;
      if (status === 'open') {
        setHidden(btnStart, true);
        setHidden(btnFinish, false);
        setHidden(btnNext, true);
        setHidden(btnEnd, true);
      } else {
        setHidden(btnStart, true);
        setHidden(btnFinish, true);
        if (isLast) {
          setHidden(btnNext, true);
          setHidden(btnEnd, false);
        } else {
          setHidden(btnNext, false);
          setHidden(btnEnd, true);
        }
      }
    } else if (status === 'finished') {
      setHidden(viewLobby, true);
      setHidden(viewQuestion, true);
      setHidden(viewOver, false);
      setHidden(btnStart, true);
      setHidden(btnFinish, true);
      setHidden(btnNext, true);
      setHidden(btnEnd, true);
    }
  }

  var lastJson = '';
  function poll() {
    fetch(stateUrl, { cache: 'no-store', credentials: 'same-origin', headers: { 'Accept': 'application/json' } })
      .then(function(resp) {
        if (!resp.ok) throw new Error('bad status ' + resp.status);
        return resp.json();
      })
      .then(function(state) {
        var s = JSON.stringify(state);
        if (s !== lastJson) {
          lastJson = s;
          render(state);
        }
      })
      .catch(function() {
        // Crowded Wi-Fi: ignore transient errors, retry next tick
      });
  }

  // Poll every 800ms (lightweight JSON, no reloads)
  setInterval(poll, 800);
  // Initial poll after short delay to sync counters without flicker
  setTimeout(poll, 400);
})();
</script>
EOF
