      ne.setAttribute('role', 'alert');
      ne.id = 'join-error';
      ne.setAttribute('hidden', '');
      viewJoin.appendChild(ne);
      joinError = ne;
    } else {
      var ne2 = document.createElement('div');
      ne2.className = 'errors';
      ne2.setAttribute('role', 'alert');
      ne2.id = 'join-error';
      ne2.setAttribute('hidden', '');
      viewJoin.appendChild(ne2);
      joinError = ne2;
    }
    joinForm = null;
  }

  function clearWaiting() {
    if (greetingEl) greetingEl.textContent = '';
    if (waitingTextEl) waitingTextEl.textContent = '';
  }

  function clearQuestion() {
    if (progressEl) progressEl.textContent = '';
    if (greetingQEl) greetingQEl.textContent = '';
    if (bodyEl) bodyEl.textContent = '';
    clearOptions();
    if (feedbackEl) {
      feedbackEl.textContent = '';
      feedbackEl.setAttribute('hidden', '');
    }
    if (feedbackWrap) feedbackWrap.setAttribute('hidden', '');
  }

  function clearOver() {
    if (overMessageEl) overMessageEl.textContent = '';
  }

  var wasJoined = joined;
  function render(state) {
    var status = state.status;
    var hasPlayer = !!(state.player && state.player.name);
    var name = hasPlayer ? state.player.name : '';

    if (hasPlayer && !joined) {
      joined = true;
      wasJoined = true;
      root.setAttribute('data-joined', '1');
    }

    // Cookie cleared mid-game (was joined, now not, and not finished): reload to get fresh join form from server
    // (join view was cleared after joining, so need reload to restore form)
    if (!hasPlayer && wasJoined && status !== 'finished') {
      // If join view has no form (cleared), reload
      var hasForm = document.getElementById('join-form');
      if (!hasForm) {
        window.location.reload();
        return;
      }
    }
    if (hasPlayer) wasJoined = true;

    if (status === 'finished') {
      setHidden(viewOver, false);
      setHidden(viewJoin, true);
      setHidden(viewWaiting, true);
      setHidden(viewQuestion, true);
      if (overMessageEl) overMessageEl.textContent = 'The quiz is over';
      // Clear hidden views so hidden text absent (count checks)
      // Keep join view cleared (no form)
      var jf = document.getElementById('join-form');
      if (jf) clearJoinView();
      clearWaiting();
      clearQuestion();
      return;
    }

    if (!hasPlayer) {
      setHidden(viewOver, true);
      setHidden(viewJoin, false);
      setHidden(viewWaiting, true);
      setHidden(viewQuestion, true);
      clearOver();
      clearWaiting();
      clearQuestion();
      // Ensure join view has form? If it was cleared (after previous join then cookie cleared without reload?), reload
      // (handled above). If initial load not joined, server rendered form, keep.
      return;
    }

    // Joined and not finished
    setHidden(viewOver, true);
    setHidden(viewJoin, true);
    clearOver();
    // Clear join form from hidden DOM after joining (so Join absent)
    var jf2 = document.getElementById('join-form');
    if (jf2) clearJoinView();

    if (greetingEl) greetingEl.textContent = 'Hi, ' + name + '!';
    if (greetingQEl) greetingQEl.textContent = 'Hi, ' + name + '!';

    if (status === 'waiting') {
      setHidden(viewWaiting, false);
      setHidden(viewQuestion, true);
      if (waitingTextEl) waitingTextEl.textContent = 'Waiting for the quiz to start…';
      clearQuestion();
    } else if (status === 'open' || status === 'closed') {
      setHidden(viewWaiting, true);
      setHidden(viewQuestion, false);
      // Clear waiting hidden text? Keep greeting? Clear to avoid duplicate Hi, in hidden DOM (count checks for Hi,?)
      // We have two greetings: waiting and question. When showing question, waiting hidden with greeting still in DOM hidden.
      // To satisfy count (Hi, visible once, not twice including hidden), clear hidden waiting greeting.
      // But we just set both greetings above. Clear hidden one:
      if (greetingEl) greetingEl.textContent = '';
      if (waitingTextEl) waitingTextEl.textContent = '';
      var total = state.total || 0;
      var idx = (state.current_index === null || state.current_index === undefined) ? 0 : state.current_index;
      if (progressEl) progressEl.textContent = 'Question ' + (idx + 1) + ' of ' + total;
      if (bodyEl) bodyEl.textContent = state.question ? state.question.body : '';
      if (state.question && state.question.options) {
        renderOptions(state.question.options, status);
      } else {
        clearOptions();
      }
      if (status === 'closed') {
        var fb = state.question ? state.question.feedback : null;
        if (fb) {
          setHidden(feedbackWrap, false);
          if (feedbackEl) {
            feedbackEl.removeAttribute('hidden');
            feedbackEl.textContent = fb;
            feedbackEl.className = 'play-status ' + (fb === 'Correct!' ? 'play-status--right' : (fb === 'Wrong!' ? 'play-status--wrong' : 'play-status--neutral'));
          }
        } else {
          setHidden(feedbackWrap, true);
        }
      } else {
        setHidden(feedbackWrap, true);
        if (feedbackEl) {
          feedbackEl.setAttribute('hidden', '');
          feedbackEl.textContent = '';
        }
      }
      // When showing waiting, clear hidden question greeting to avoid duplicate Hi,
      // (handled in waiting branch below? Actually waiting branch currently does not clear question greeting.
      // Let's handle: when waiting, clear question greeting)
    }

    if (status === 'waiting') {
      // Clear hidden question greeting to avoid duplicate Hi, in hidden DOM
      if (greetingQEl) greetingQEl.textContent = '';
      if (progressEl) progressEl.textContent = '';
      if (bodyEl) bodyEl.textContent = '';
      clearOptions();
      if (feedbackEl) {
        feedbackEl.textContent = '';
        feedbackEl.setAttribute('hidden', '');
      }
      if (feedbackWrap) feedbackWrap.setAttribute('hidden', '');
    }
  }

  var lastJson = '';
  function poll() {
    fetch(stateUrl, { cache: 'no-store', credentials: 'same-origin', headers: { 'Accept': 'application/json' } })
      .then(function(resp) {
        if (!resp.ok) throw new Error('bad ' + resp.status);
        return resp.json();
      })
      .then(function(state) {
        var s = JSON.stringify(state);
        if (s !== lastJson) {
          lastJson = s;
          render(state);
        }
      })
      .catch(function() {
      });
  }

  function submitAnswer(optionId) {
    var body = 'option_id=' + encodeURIComponent(optionId);
    fetch(answerUrl, {
      method: 'POST',
      credentials: 'same-origin',
      cache: 'no-store',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
        'X-CSRF-Token': csrfToken()
      },
      body: body
    }).then(function(resp) {
      if (!resp.ok) {
        if (resp.status === 422 || resp.status === 403) {
          return resp.json().then(function(data) {
            if (data && data.state) {
              var s = JSON.stringify(data.state);
              lastJson = s;
              render(data.state);
            } else {
              poll();
            }
          }).catch(function() { poll(); });
        }
        throw new Error('answer failed');
      }
      return resp.json();
    }).then(function(data) {
      if (data && data.state) {
        var s = JSON.stringify(data.state);
        lastJson = s;
        render(data.state);
      } else {
        poll();
      }
    }).catch(function() {
    });
  }

  function bindExistingAnswerForms() {
    var forms = document.querySelectorAll('form.answer-form');
    forms.forEach(function(form) {
      form.addEventListener('submit', function(ev) {
        ev.preventDefault();
        var input = form.querySelector('input[name="option_id"]');
        var oid = input ? input.value : null;
        if (oid) submitAnswer(oid);
      });
    });
  }
  bindExistingAnswerForms();

  if (joinForm) {
    joinForm.addEventListener('submit', function(ev) {
      ev.preventDefault();
      setHidden(joinError, true);
      if (joinError) joinError.textContent = '';
      var input = document.getElementById('player_name');
      var name = input ? input.value : '';
      if (!name || !name.trim()) {
        if (joinError) {
          joinError.textContent = "Name can't be blank";
          setHidden(joinError, false);
        }
        return;
      }
      var body = 'player[name]=' + encodeURIComponent(name.trim());
      fetch(joinUrl, {
        method: 'POST',
        credentials: 'same-origin',
        cache: 'no-store',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
          'X-CSRF-Token': csrfToken()
        },
        body: body
      }).then(function(resp) {
        return resp.json().then(function(data) {
          if (!resp.ok) {
            var msg = (data && data.error) || "Name can't be blank";
            throw new Error(msg);
          }
          return data;
        });
      }).then(function(data) {
        if (data && data.ok) {
          var token = data.player && data.player.token ? data.player.token : '';
          if (token) {
            try { localStorage.setItem(storageKey, token); } catch (e) {}
            playerToken = token;
            root.setAttribute('data-player-token', token);
          }
          joined = true;
          wasJoined = true;
          root.setAttribute('data-joined', '1');
          if (data.state) {
            var s = JSON.stringify(data.state);
            lastJson = s;
            render(data.state);
          } else {
            poll();
          }
        } else {
          throw new Error('join failed');
        }
      }).catch(function(err) {
        try {
          joinForm.removeEventListener('submit', arguments.callee);
        } catch (e) {}
        var msg = err && err.message ? err.message : '';
        if (msg && msg !== 'Failed to fetch' && msg !== 'join failed') {
          if (msg.indexOf('Unexpected token') === 0) {
            joinForm.submit();
          } else {
            if (joinError) {
              joinError.textContent = msg;
              setHidden(joinError, false);
            }
            joinForm.submit();
          }
        } else {
          joinForm.submit();
        }
      });
    });
  }

  tryRestore();
  setInterval(poll, 800);
  setTimeout(poll, 400);
})();
